// Some portions generated by Claude
import test from 'node:test';
import assert from 'node:assert/strict';
import {separateLayoutRectangles} from '../../../main/frontend/graph-explorer/graph-layout-network.ts';
import {computeSparseLayout} from '../../../main/frontend/graph-explorer/graph-layout-sparse.ts';
import {computeGraphLayout} from '../../../main/frontend/graph-explorer/graph-layout-engine.ts';
import {graphNodeSize} from '../../../main/frontend/graph-explorer/graph-geometry.ts';
import {coincidentCards, wideGrid, groupedNetwork} from './fixtures/layout-adversarial.mjs';
import {layoutDimensionsChanged} from '../../../main/frontend/graph-explorer/graph-model.ts';
import {layoutNeighborhoods} from '../../../main/frontend/graph-explorer/graph-layout-groups.ts';
import {cycleNetwork, bipartiteNetwork, karateNetwork, gridNetwork} from './fixtures/layout-diverse.mjs';
import {chainNetwork, sharedHubNetwork} from './fixtures/layout-networks.mjs';
import {indexedIntersections, intersectingGroupBoxes} from './fixtures/layout-measurements.mjs';
import {layoutMetrics} from './support/benchmark-layout.mjs';
import {SpatialGrid} from '../../../main/frontend/graph-explorer/spatial-grid.ts';

function intersections(graph, positions) {
  let overlaps = 0;
  const nodes = graph.nodes.map(n => ({...positions.get(n.id), ...graphNodeSize(n)}));
  for (let a = 0; a < nodes.length; a++) for (let b = a + 1; b < nodes.length; b++) {
    const p = nodes[a], q = nodes[b];
    if (Math.abs(p.x - q.x) < (p.width + q.width) / 2 - 1e-5 &&
        Math.abs(p.y - q.y) < (p.height + q.height) / 2 - 1e-5) overlaps++;
  }
  return overlaps;
}

test('overlap repair finishes a dense pile without moving the pinned anchor', () => {
  const graph = coincidentCards();
  const positions = new Map(graph.nodes.map(n => [n.id, {x: n.x, y: n.y}]));
  separateLayoutRectangles(graph, positions);
  assert.deepEqual(positions.get('0'), {x: 0, y: 0});
  assert.equal(intersections(graph, positions), 0);
});

test('large local layout uses actual card bounds, not rounded occupancy cells', () => {
  const graph = wideGrid();
  const result = computeSparseLayout(graph, {incremental: true, movableNodeIds: new Set(graph.nodes.map(n => n.id))});
  assert.equal(intersections(graph, result.positions), 0);
});

test('late labels trigger geometry repair but animation and same-sized labels do not', async () => {
  const before = [{id: 'a', label: 'A', kind: 'iri', x: 0, y: 0}, {id: 'b', label: 'B', kind: 'iri', x: 160, y: 0}];
  const after = before.map(n => ({...n, label: 'A descriptive label that is wider than the initial identifier'}));
  assert.equal(layoutDimensionsChanged(before, before.map(n => ({...n, x: n.x + 70}))), false);
  assert.equal(layoutDimensionsChanged(before, before.map(n => ({...n, label: 'X'}))), false);
  assert.equal(layoutDimensionsChanged(before, after), true);
  const graph = {nodes: after, edges: [], revision: 1};
  const result = await computeGraphLayout(graph, {repairOnly: true});
  assert.equal(intersections(graph, result.positions), 0);
});

test('named groups reach the layout and do not interleave with other groups', async () => {
  const {graph, groups} = groupedNetwork();
  const result = await computeGraphLayout(graph, {groups});
  assert.equal(intersections(graph, result.positions), 0);
  const byId = new Map(graph.nodes.map(n => [n.id, n]));
  const boxes = groups.map(group => {
    const entries = group.nodeIds.map(id => ({...result.positions.get(id), ...graphNodeSize(byId.get(id))}));
    return {minX: Math.min(...entries.map(n => n.x - n.width / 2)), maxX: Math.max(...entries.map(n => n.x + n.width / 2)),
      minY: Math.min(...entries.map(n => n.y - n.height / 2)), maxY: Math.max(...entries.map(n => n.y + n.height / 2))};
  });
  for (let a = 0; a < boxes.length; a++) for (let b = a + 1; b < boxes.length; b++) {
    const p = boxes[a], q = boxes[b];
    assert.ok(p.maxX <= q.minX || q.maxX <= p.minX || p.maxY <= q.minY || q.maxY <= p.minY,
      `group ${a} and ${b} bounding boxes overlap`);
  }
});

test('pinned named groups retain their anchor and stay separate from free groups', async () => {
  const {graph, groups} = groupedNetwork(3, 10);
  graph.nodes[0].pinned = true;
  graph.nodes[0].x = -600; graph.nodes[0].y = -400;
  const result = await computeGraphLayout(graph, {groups});
  assert.deepEqual(result.positions.get('0'), {x: -600, y: -400});
  assert.equal(intersections(graph, result.positions), 0);
  assert.equal(result.grouped, true);
  assert.equal(intersectingGroupBoxes(graph, result.positions, groups), 0);
});

test('contradictory pins are reported without silently moving pinned nodes', async () => {
  const graph = coincidentCards(12); graph.nodes[1].pinned = true;
  const result = await computeGraphLayout(graph, {repairOnly: true});
  assert.deepEqual(result.positions.get('0'), {x: 0, y: 0});
  assert.deepEqual(result.positions.get('1'), {x: 0, y: 0});
  assert.equal(result.fixedOverlaps, 1);
  assert.equal(intersections(graph, result.positions), 1);
});

test('automatic neighborhoods are connected, and weak evidence stays ungrouped', () => {
  for (const graph of [chainNetwork(), cycleNetwork(), bipartiteNetwork()]) {
    assert.ok(layoutNeighborhoods(graph).groups.every(group => group.length === 1));
  }
  const graph = sharedHubNetwork(), {groups, topology} = layoutNeighborhoods(graph);
  assert.equal(groups.filter(group => group.length > 1).length, 8);
  for (const members of groups) {
    const allowed = new Set(members.map(String)), visited = new Set([String(members[0])]), queue = [...visited];
    for (let i = 0; i < queue.length; i++) topology.forEachNeighbor(queue[i], next => {
      if (allowed.has(next) && !visited.has(next)) {visited.add(next); queue.push(next);}
    });
    assert.equal(visited.size, members.length);
  }
});

test('overlapping named groups merge consistently and unknown members are ignored', () => {
  const graph = chainNetwork(8);
  const groups = [{id: 'a', nodeIds: ['0', '1', 'missing']}, {id: 'b', nodeIds: ['1', '2']}];
  assert.deepEqual(layoutNeighborhoods(graph, {groups}).groups[0], [0, 1, 2]);
});

test('public social graph and held-out grid remain complete and overlap-free', async () => {
  const karate = karateNetwork();
  assert.equal(karate.nodes.length, 34); assert.equal(karate.edges.length, 78);
  for (const graph of [karate, gridNetwork(), cycleNetwork()]) {
    const before = structuredClone(graph), result = await computeGraphLayout(graph);
    assert.equal(result.positions.size, graph.nodes.length);
    assert.equal(indexedIntersections(graph, result.positions), 0);
    assert.deepEqual(graph, before);
  }
});

test('automatic grouping must not degrade an ordinary social network', async () => {
  const graph = karateNetwork(), result = await computeGraphLayout(graph);
  const metrics = layoutMetrics(graph, result.positions);
  assert.ok(metrics.edgeCrossings <= 80, `crossings: ${metrics.edgeCrossings}`);
  assert.ok(metrics.p95Edge < 750, `95th-percentile edge length: ${metrics.p95Edge}`);
});

test('named group boxes are compacted without stretching a small graph into a strip', async () => {
  const {graph, groups} = groupedNetwork();
  const result = await computeGraphLayout(graph, {groups});
  assert.equal(intersectingGroupBoxes(graph, result.positions, groups), 0);
  assert.ok(layoutMetrics(graph, result.positions).p95Edge < 1500);
});

test('geometry-only repair does not rearrange clear but interleaved group boxes', async () => {
  const {graph, groups} = groupedNetwork();
  graph.nodes.forEach((n, i) => {n.x = i % 6 * 340; n.y = Math.floor(i / 6) * 160;});
  // Explicit membership spans multiple rows; all cards already have clearance.
  groups.forEach((g, c) => {g.nodeIds = graph.nodes.filter((_, i) => i % 4 === c).map(n => n.id);});
  const result = await computeGraphLayout(graph, {groups, repairOnly: true});
  for (const n of graph.nodes) assert.deepEqual(result.positions.get(n.id), {x: n.x, y: n.y});
});

test('an infeasible pile of fixed nodes has a bounded diagnostic cost', () => {
  const graph = coincidentCards(1000); graph.nodes.forEach(n => {n.pinned = true;});
  const positions = new Map(graph.nodes.map(n => [n.id, {x: n.x, y: n.y}]));
  const original = SpatialGrid.prototype.search; let queries = 0;
  SpatialGrid.prototype.search = function(...args) {queries++; return original.apply(this, args);};
  try {
    const status = separateLayoutRectangles(graph, positions, {repairOnly: true});
    assert.ok(status.fixedOverlaps >= 1000);
    assert.ok(queries < 100, `overlap diagnostics queried ${queries} times`);
    for (const p of positions.values()) assert.deepEqual(p, {x: 0, y: 0});
  } finally {SpatialGrid.prototype.search = original;}
});
